import{_ as e,o as a,c as s,a2 as o}from"./chunks/framework.ChIlRNAd.js";const m=JSON.parse('{"title":"Attachments","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/attachments.md","filePath":"en/guide/attachments.md"}'),n={name:"en/guide/attachments.md"};function r(i,t,c,l,h,d){return a(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="attachments" tabindex="-1">Attachments <a class="header-anchor" href="#attachments" aria-label="Permalink to &quot;Attachments&quot;">​</a></h1><p>The <strong>Attachments</strong> page (<code>/attachments</code>) lists every attachment of the active account, heaviest first. It has no sidebar entry: open it from the command palette (<code>⌘K</code> / <code>Ctrl+K</code>, <strong>Other pages</strong> group).</p><p>For a quick sort of large mails with bulk actions, the <strong>Large mails &amp; attachments</strong> tab of <a href="./cleanup.html#large-mails-attachments">Cleanup</a> is usually enough.</p><hr><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><p>Two buttons pick the source:</p><ul><li><strong>Archives</strong> (default): attachments of the mails saved on the NAS. A search <strong>by name, subject, sender or content</strong> is available: the text of PDFs and Word documents (.docx) is searched too (same rules as the <a href="./archives.html">Archives</a> search: accent-insensitive, <code>&quot;exact phrase&quot;</code>, <code>-exclude</code>, <code>OR</code>), and the matching excerpt shows under the file name.</li><li><strong>Live</strong>: attachments over 100 KB still in Gmail.</li></ul><p>Source, search and page are kept in the address. <strong>Reload</strong> fetches the list again.</p><hr><h2 id="indicators" tabindex="-1">Indicators <a class="header-anchor" href="#indicators" aria-label="Permalink to &quot;Indicators&quot;">​</a></h2><ul><li><strong>Attachments</strong>: number of files;</li><li><strong>Total size</strong>;</li><li><strong>Source</strong>: &quot;Local archives&quot; or &quot;Gmail (&gt;100 KB)&quot;;</li><li><strong>Space saved</strong>: gain from deduplicating archived attachments (&quot;N duplicate file(s), X saved&quot;). An identical file (same content) is written once per account, whether the mail comes from a Gmail backup, an IMAP account or an mbox / .eml import. If some files archived before this deduplication have not been analyzed yet, the <strong>Analyze</strong> button runs it and merges the duplicates.</li></ul><hr><h2 id="list" tabindex="-1">List <a class="header-anchor" href="#list" aria-label="Permalink to &quot;List&quot;">​</a></h2><p>Columns: <strong>File</strong>, <strong>Email</strong>, <strong>Size</strong>, <strong>Date</strong>, <strong>Type</strong>, <strong>Actions</strong>. The list is paginated.</p><ul><li><strong>Download</strong>: saves the file.</li><li><strong>View</strong>: opens the file in the browser, only for images (PNG, JPEG, GIF, WebP) and PDFs.</li></ul>',15)])])}const g=e(n,[["render",r]]);export{m as __pageData,g as default};
